#include <stdio.h>

int main(void) {
    int n, price;
    int count[1001] = {0};
    long long total = 0;
    int position = 0;

    if (scanf("%d", &n) != 1) return 0;

    for (int i = 0; i < n; i++) {
        scanf("%d", &price);
        count[price]++;
        total += price;
